description:
The auto-resolve of the license and export branches kept the license builder's stub run() instead of the export builder's full implementation. Fix by combining them.

The run() function at line 46-53 of crates/xray-cli/src/commands/export.rs currently reads:
  pub fn run(_args: ExportArgs) -> Result<(), Box<dyn std::error::Error>> {
      if !license::is_pro() { ... exit(4); }
      eprintln!('not yet implemented');
      Ok(())
  }

Replace with the export builder's full implementation plus the license gate:
  pub fn run(args: ExportArgs) -> Result<(), Box<dyn std::error::Error>> {
      if !license::is_pro() {
          eprintln!('License required. Run: xray license activate <key>');
          std::process::exit(4);
      }
      let root = std::path::Path::new(&args.path).canonicalize()...
      let cache_dir = root.join('.xray');
      let graph_bin_path = cache_dir.join('graph.bin');
      let graph = match graph_bin::load(&graph_bin_path) { Ok(Some(g)) => g, _ => build_graph(&root, &cache_dir)? };
      let from = match &args.from { Some(f) => f.clone(), None => return Err('--from is required'.into()) };
      let export = extract_subgraph(&graph, &from, args.depth, &args.direction, args.max_nodes);
      let exported_at = utc_now_iso8601();
      let output_str = match args.format.as_str() { 'json' => to_ai_json(&export, &exported_at)?, _ => to_ai_markdown(&export, &exported_at) };
      if let Some(output_file) = &args.output { std::fs::write(output_file, &output_str)?; } else { println!('{}', output_str); }
      Ok(())
  }

Only file to change: crates/xray-cli/src/commands/export.rs (the run function, lines 46-53)
